import { defineSlot } from '../Slot';

/**
 * The body of the active sheet, rendered once a user is signed in and a sheet is loaded. A
 * feature that shows or changes a sheet's data fills this region. Its data lives under query
 * keys starting ['sheet', sheetId, ...]: loading a sheet drops every such key, so the whole
 * sheet is re-read from the store.
 */
export const SheetBody = defineSlot<{ sheetId: string; user: string }>('sheet.body');
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { peopleKey, useWatched, type Person } from '../people/usePeople';
import { usePersonRowAction } from '../people/usePersonRowAction';

/** Whether the signed-in user watches the person (yes/no), and a button that toggles it. A watcher is told
 *  (server side) when one of the person's claims is settled, approved or re-settled. */
function PersonWatch({ sheetId, personId }: { sheetId: string; personId: number }) {
  const watchedIds = useWatched(sheetId);
  const queryClient = useQueryClient();
  const watched = (watchedIds.data ?? []).includes(personId);

  const watch = useMutation({
    mutationFn: (body: { watch: boolean }) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/watch`, body),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
  });
  const announce = usePersonRowAction(sheetId, personId, watch.reset);

  return (
    <td>
      <span data-testid="person-watched">{watched ? 'yes' : 'no'}</span>{' '}
      <button
        type="button"
        data-testid="person-watch"
        disabled={watch.isPending || !watchedIds.isSuccess}
        onClick={() => {
          announce();
          watch.reset();
          watch.mutate({ watch: !watched });
        }}
      >
        {watched ? 'Unwatch' : 'Watch'}
      </button>
      {watch.isError && <span data-testid="person-error">{watch.error.message}</span>}
    </td>
  );
}

export const contributions = [
  PersonColumnHead.fill({ order: 55, Component: () => <th>Watched</th> }),
  PersonCells.fill({ order: 55, Component: PersonWatch }),
];
package net.officefloor.hq.app;

import net.officefloor.server.http.HttpHeader;
import net.officefloor.server.http.ServerHttpConnection;

/** The signed-in user of a request: the name the front end sends in the X-User header. */
public final class CurrentUser {
    public static final String HEADER = "X-User";

    private CurrentUser() {
    }

    /** The trimmed name, refused when blank. A step takes the {@link ServerHttpConnection} and
     *  passes it here (header names are matched ignoring case, as browsers send them lower-case). */
    public static String require(ServerHttpConnection connection) throws BadRequestException {
        String name = "";
        for (HttpHeader header : connection.getRequest().getHeaders()) {
            if (HEADER.equalsIgnoreCase(header.getName())) {
                name = header.getValue() == null ? "" : header.getValue().trim();
                break;
            }
        }
        if (name.isEmpty()) {
            throw new BadRequestException("not signed in");
        }
        return name;
    }
}

